-- the Runner can read it rather than only in this generator.
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Currents';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Recurrents';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold';
UPDATE categories SET rdj_subcategory_ids = ARRAY[30]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Discovery';
UPDATE categories SET rdj_subcategory_ids = ARRAY[5]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'A1';
UPDATE categories SET rdj_subcategory_ids = ARRAY[3]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'A2';
UPDATE categories SET rdj_subcategory_ids = ARRAY[6]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'B';
UPDATE categories SET rdj_subcategory_ids = ARRAY[23]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'C';
UPDATE categories SET rdj_subcategory_ids = ARRAY[24]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'N';
UPDATE categories SET rdj_subcategory_ids = ARRAY[26]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'R1';
UPDATE categories SET rdj_subcategory_ids = ARRAY[27]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'R2';
UPDATE categories SET rdj_subcategory_ids = ARRAY[28]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'R3';
UPDATE categories SET rdj_subcategory_ids = ARRAY[29]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'G2010';
UPDATE categories SET rdj_subcategory_ids = ARRAY[4]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'G2000';
UPDATE categories SET rdj_subcategory_ids = ARRAY[1]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'G1990';
UPDATE categories SET rdj_subcategory_ids = ARRAY[2]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'H1';
UPDATE categories SET rdj_subcategory_ids = ARRAY[36]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'H2';
UPDATE categories SET rdj_subcategory_ids = ARRAY[25]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'F';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'GDEEP';
UPDATE categories SET rdj_subcategory_ids = ARRAY[54]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Back-sell';
UPDATE categories SET rdj_subcategory_ids = ARRAY[60]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Discovery Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[53]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Front-sell';
UPDATE categories SET rdj_subcategory_ids = ARRAY[63]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 00s';
UPDATE categories SET rdj_subcategory_ids = ARRAY[64]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 10s';
UPDATE categories SET rdj_subcategory_ids = ARRAY[62]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold 90s';
UPDATE categories SET rdj_subcategory_ids = ARRAY[41]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Gold Backsells';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Heritage Backsells';
UPDATE categories SET rdj_subcategory_ids = ARRAY[37,52]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Liners';
UPDATE categories SET rdj_subcategory_ids = ARRAY[56]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'New Music Back';
UPDATE categories SET rdj_subcategory_ids = ARRAY[38,55]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'New-Music Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[59]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Power';
UPDATE categories SET rdj_subcategory_ids = ARRAY[61]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Recurrent Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[40]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Relaunch Sweepers';
UPDATE categories SET rdj_subcategory_ids = ARRAY[43]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'Station Promos';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH CO';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH DN';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH EM';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH ES';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH FF';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH GH';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH HD';
UPDATE categories SET rdj_subcategory_ids = ARRAY[42]::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH IDs';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH WD';
UPDATE categories SET rdj_subcategory_ids = '{}'::int[] WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'TOH WW';
UPDATE categories SET rest_review_days = 90 WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'A1' AND rest_review_days IS NULL;
UPDATE categories SET rest_review_days = 90 WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'A2' AND rest_review_days IS NULL;
UPDATE categories SET rest_review_days = 90 WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'B' AND rest_review_days IS NULL;
UPDATE categories SET rest_review_days = 90 WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'C' AND rest_review_days IS NULL;
UPDATE categories SET rest_review_days = 90 WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND name = 'N' AND rest_review_days IS NULL;
UPDATE stations SET rdj_lifecycle_subcats = '{"31":{"state":"benched"},"32":{"state":"resting"},"33":{"state":"resting","origin":"N"},"34":{"state":"retired"},"35":{"state":"benched","default":true}}'::jsonb WHERE id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';

-- Derived membership, for a station not yet imported (ADR-0002 §4). Identity is the
-- RadioDJ subcategory ID; the mirror follows RadioDJ (ADR-0001 §3.2 stage 1). Once the
-- station is imported this inserts nothing and authored membership stands.
SELECT s.id, c.id FROM songs s JOIN categories c ON c.station_id = s.station_id
WHERE s.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND (SELECT membership_imported_at FROM stations WHERE id = '6a42a599-acfc-404f-a524-9fb9b65d36f3') IS NULL AND (
  (c.name = 'A1' AND s.rdj_subcategory_id = 5) OR
  (c.name = 'A2' AND s.rdj_subcategory_id = 3) OR
  (c.name = 'B' AND s.rdj_subcategory_id = 6) OR
  (c.name = 'C' AND s.rdj_subcategory_id = 23) OR
  (c.name = 'N' AND s.rdj_subcategory_id = 24) OR
  (c.name = 'R1' AND s.rdj_subcategory_id = 26) OR
  (c.name = 'R2' AND s.rdj_subcategory_id = 27) OR
  (c.name = 'R3' AND s.rdj_subcategory_id = 28) OR
  (c.name = 'G2010' AND s.rdj_subcategory_id = 29) OR
  (c.name = 'G2000' AND s.rdj_subcategory_id = 4) OR
  (c.name = 'G1990' AND s.rdj_subcategory_id = 1) OR
  (c.name = 'H1' AND s.rdj_subcategory_id = 2) OR
  (c.name = 'H2' AND s.rdj_subcategory_id = 36) OR
  (c.name = 'Discovery' AND s.rdj_subcategory_id = 30) OR
  (c.name = 'F' AND s.rdj_subcategory_id = 25) OR
  (c.name = 'TOH IDs' AND s.rdj_subcategory_id = 42) OR
  (c.name = 'Liners' AND s.rdj_subcategory_id IN (37,52)) OR
  (c.name = 'New-Music Sweepers' AND s.rdj_subcategory_id IN (38,55)) OR
  (c.name = 'Gold Backsells' AND s.rdj_subcategory_id = 41) OR
  (c.name = 'Relaunch Sweepers' AND s.rdj_subcategory_id = 40) OR
  (c.name = 'Station Promos' AND s.rdj_subcategory_id = 43) OR
  (c.name = 'Front-sell' AND s.rdj_subcategory_id = 53) OR
  (c.name = 'Back-sell' AND s.rdj_subcategory_id = 54) OR
  (c.name = 'New Music Back' AND s.rdj_subcategory_id = 56) OR
  (c.name = 'Power' AND s.rdj_subcategory_id = 59) OR
  (c.name = 'Discovery Sweepers' AND s.rdj_subcategory_id = 60) OR
  (c.name = 'Recurrent Sweepers' AND s.rdj_subcategory_id = 61) OR
  (c.name = 'Gold 90s' AND s.rdj_subcategory_id = 62) OR
  (c.name = 'Gold 00s' AND s.rdj_subcategory_id = 63) OR
  (c.name = 'Gold 10s' AND s.rdj_subcategory_id = 64)
)
ON CONFLICT ON CONSTRAINT song_categories_song_category_unique DO NOTHING;

-- One clock per block. GHa/GHb and DNa/DNb are variants of one identity (see
-- IDENTITY in m4-format.mjs) and share a TOH pool, but are separate clocks because
-- their position order differs.

-- Clock positions. Music is placed by two-level proportional spread (tier first, then
-- category within tier); imaging is woven in contextually — a New-Music sweeper ahead
-- of a new track, a Gold Backsell behind a gold one. Emitted from clockSequence() so
-- this matches tools/clock-order.mjs exactly.
--
-- constraints.fallbackCategoryId is the governing fallback policy: currents never
-- fall back to gold. Unplanned fallback is still programming — under M3, G2010 carried
-- 651 fallback slots on top of its own 368, and the station's gold-heavy sound was a
-- symptom of shallow currents rather than a design choice.

-- Format grid: 336 cells (2 weeks x 168 hours), station-local.
-- Golden Hour resolves to GHa or GHb by (week + dow) % 2, so a listener in a fixed
-- weekly slot gets the other variant next week.

-- Rules. Vertical separation (artist/title) keeps unlike things apart within an hour;
-- horizontal separation keeps a song off the same TIME OF DAY on successive plays.
--
-- Horizontal is scoped to currents and R1 ONLY. Applied uniformly it made things
-- worse — R1 lost 19pp and Discovery yielded on 93% of slots, and a yield drops album
-- separation and tempo clash with it. Params are yield-capped at <=25%.

-- Assert the seed landed. A silent partial seed is far worse than a failed one: the
-- station would generate logs against a half-built clockset and nobody would know
-- until air. Each check aborts the transaction rather than warning.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM clocks WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 11 THEN RAISE EXCEPTION 'expected 11 clocks, got %', n; END IF;
  SELECT count(*) INTO n FROM format_grid WHERE station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 336 THEN RAISE EXCEPTION 'expected 336 grid cells, got %', n; END IF;
  SELECT count(*) INTO n FROM clock_positions cp JOIN clocks c ON c.id = cp.clock_id
    WHERE c.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3';
  IF n <> 298 THEN RAISE EXCEPTION 'expected 298 clock positions, got %', n; END IF;
  -- Every position must resolve a category. A NULL here is a category name in the
  -- generator that does not exist in the categories table — the M2-era failure where
  -- subcategory 34 sat unmapped and nobody noticed.
  SELECT count(*) INTO n FROM clock_positions cp JOIN clocks c ON c.id = cp.clock_id
    WHERE c.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3' AND cp.category_id IS NULL;
  IF n > 0 THEN RAISE EXCEPTION '% clock positions have no category', n; END IF;
  -- Every music category a clock calls must actually have songs mapped to it.
  SELECT count(*) INTO n FROM categories cat WHERE cat.station_id = '6a42a599-acfc-404f-a524-9fb9b65d36f3'
    AND cat.kind = 'music' AND cat.parent_id IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM song_categories sc WHERE sc.category_id = cat.id);
  IF n > 0 THEN RAISE EXCEPTION '% music categories have no songs — re-sync the library first', n; END IF;
END $$;

COMMIT;
